+;     return
+; }
+
+;; Cross block: idempotent store in dominated block should be removed.
+function %cross_block_dominated(i64) {
+block0(v0: i64):
+    v1 = load.i32 heap v0+8
+    jump block1
+
+block1:
+    store.i32 heap v1, v0+8
+    return
+}
+
+; function %cross_block_dominated(i64) fast {
+; block0(v0: i64):
+;     v1 = load.i32 heap v0+8
